def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1
    chars = []
    seen = set()
    for ch in alphabet:
        if ch not in seen:
            seen.add(ch)
            chars.append(ch)
    A = len(chars)
    cid = {ch: i for i, ch in enumerate(chars)}

    nxt = [[-1] * A]
    fail = [0]
    out = [False]

    def add_node():
        nxt.append([-1] * A)
        fail.append(0)
        out.append(False)
        return len(nxt) - 1

    for word in set(banned):
        u = 0
        for ch in word:
            c = cid[ch]
            if nxt[u][c] == -1:
                nxt[u][c] = add_node()
            u = nxt[u][c]
        out[u] = True

    from collections import deque
    q = deque()
    for c in range(A):
        v = nxt[0][c]
        if v != -1:
            fail[v] = 0
            q.append(v)
        else:
            nxt[0][c] = 0
    while q:
        u = q.popleft()
        if out[fail[u]]:
            out[u] = True
        for c in range(A):
            v = nxt[u][c]
            if v != -1:
                fail[v] = nxt[fail[u]][c]
                q.append(v)
            else:
                nxt[u][c] = nxt[fail[u]][c]

    safe = [i for i, bad in enumerate(out) if not bad]
    remap = {s: i for i, s in enumerate(safe)}
    m = len(safe)
    if 0 not in remap:
        return 0
    root = remap[0]
    M = [[0] * m for _ in range(m)]
    for s in safe:
        si = remap[s]
        for c in range(A):
            t = nxt[s][c]
            if not out[t]:
                M[remap[t]][si] += 1

    def mul(X, Y):
        r = len(X)
        c = len(Y[0])
        k = len(Y)
        Z = [[0] * c for _ in range(r)]
        for i in range(r):
            Xi = X[i]
            Zi = Z[i]
            for t in range(k):
                a = Xi[t]
                if a:
                    Yt = Y[t]
                    for j in range(c):
                        Zi[j] = (Zi[j] + a * Yt[j]) % MOD
        return Z

    res = [[1 if i == j else 0 for j in range(m)] for i in range(m)]
    base = M
    e = n
    while e:
        if e & 1:
            res = mul(res, base)
        base = mul(base, base)
        e >>= 1
    return sum(res[i][root] for i in range(m)) % MOD
